export function getAbilityDefinition(abilityId, { template = false } = {}) {
  const infiltrationMatch = abilityId?.match(/^ABILITY_INFILTRATE_(\d+)$/);
  if (infiltrationMatch) {
    const value = Number(infiltrationMatch[1]);
    const definition = ABILITIES.ABILITY_INFILTRATE_X;
    if (template) return definition;
    return {
      ...definition,
      name: `渗透${value}`,
      description: `每个渗透周期提供${value}点渗透值。`,
      value,
      templateId: "ABILITY_INFILTRATE_X",
    };
  }
  return ABILITIES[abilityId] ?? SPECIAL_ABILITIES[abilityId];
}

export function getRace(id) {
  return RACES.find((race) => race.id === id);
}

export function getJob(id) {
  return JOBS.find((job) => job.id === id);
}

export function getComponent(id) {
  const normalizedId = normalizeBiofactorId(id);
  return COMPONENTS.find((component) => component.id === normalizedId);
}

export function isContentUnlocked(content, state) {
  if (state?.settings?.testMode) return true;
  if (content?.systemOnly) return false;
  if (state?.unlockedBiofactors?.includes(content?.id)) return true;
  if (state?.rewardProgress?.unlockedContentIds?.includes(content?.id)) {
    return true;
  }
  if (!content?.unlock || content.unlock.type === "COMMON") return true;
  if (content.unlock.type === "BIOFACTOR") {
    return state.unlockedBiofactors.includes(content.unlock.biofactorId);
  }
  if (content.unlock.type === "ORIGIN") {
    const originColor = state.base.originId.slice(-1);
    return content.unlock.colors.includes(originColor);
  }
  return false;
}
